const svg=(body,view='0 0 120 120')=>`<svg viewBox="${view}" aria-hidden="true" xmlns="http://www.w3.org/2000/svg">${body}</svg>`;
export function topArt(f){const id='finish-'+Math.random().toString(36).slice(2),wood=f.upgraded?['#d9ab6b','#a76a37']:['#ab8a62','#786047'];const defs=`<defs><linearGradient id="${id}" x2=".8" y2="1"><stop stop-color="${wood[0]}"/><stop offset="1" stop-color="${wood[1]}"/></linearGradient></defs>`;let grain='<path d="M17 25q26-5 80 0M17 50q35 5 80 0M17 76q50-5 80 0M17 98q31 4 80 0" fill="none" stroke="#68401f" stroke-width="1" opacity=".28"/>';if(f.type==='light')return svg(`<circle cx="62" cy="64" r="24" fill="#302514" opacity=".25"/><circle cx="60" cy="60" r="23" fill="${f.upgraded?'#486849':'#786b55'}" stroke="#493322" stroke-width="3"/><circle cx="60" cy="60" r="18" fill="none" stroke="${f.upgraded?'#8d9b65':'#9b8661'}" stroke-width="2"/><path d="M46 57q4-13 17-12" stroke="#e3d49d" stroke-width="3" fill="none" opacity=".6"/><circle cx="60" cy="60" r="7" fill="${f.upgraded?'#fff5ac':'#b3a47e'}" stroke="#5b4828" stroke-width="2"/>`);if(f.type==='table')return svg(defs+`<rect x="9" y="12" width="107" height="105" rx="7" fill="#302010" opacity=".27"/><rect x="6" y="6" width="108" height="108" rx="6" fill="#724c2c" stroke="#51331f" stroke-width="2.5"/><rect x="10" y="9" width="100" height="99" rx="4" fill="url(#${id})" stroke="#dbb17b" stroke-width="1.5"/>${grain}<path d="M12 35h96M12 62h96M12 87h96" stroke="#6b4329" stroke-width="1.3" opacity=".5"/><ellipse cx="80" cy="49" rx="9" ry="3" fill="none" stroke="#85562d" opacity=".45"/>${f.upgraded?'':'<path d="m26 18 17 12-6 3m33 34 16 13-9 3M18 83l21 5" stroke="#4b3a2a" stroke-width="1.7" fill="none"/><path d="m37 48 20 3m-31 47 17-3" stroke="#dbc4a0" stroke-width="2" opacity=".5"/>'}`);return svg(defs+`<rect x="30" y="37" width="63" height="65" rx="7" fill="#302010" opacity=".25"/><rect x="28" y="30" width="64" height="65" rx="7" fill="#76502f" stroke="#4c321f" stroke-width="2.5"/><rect x="32" y="33" width="56" height="57" rx="7" fill="url(#${id})"/><path d="M35 46q25-7 50 0M35 72q25 7 50 0" stroke="#674021" opacity=".3" fill="none"/><rect x="25" y="22" width="70" height="16" rx="5" fill="url(#${id})" stroke="#4d341f" stroke-width="2.5"/><path d="M30 25h60" stroke="#e4c38d" opacity=".6"/>${f.upgraded?'':'<path d="m41 49 21 4-8 4m4 17 16 4" stroke="#51402f" stroke-width="1.7" fill="none"/>'}`)}
export function planArt(state,wasteSpots,projectWaste){let floor=state.floor?'#c09056':'#91704d',wall=state.paint?'#ebd5ae':'#bbab8e';let boards='';for(let x=203,i=0;x<1355;x+=57,i++){for(let y=125-(i%2)*90;y<910;y+=180){let yy=Math.max(125,y),h=Math.min(y+180,910)-yy;boards+=`<rect x="${x}" y="${yy}" width="57" height="${h}" fill="${i%3===0?'#ffe0a2':'#3c2211'}" opacity="${i%3===0?.06:.025}" stroke="#5a3b23" stroke-width="1.3"/><path d="M${x+12} ${yy+7}q-5 ${h/3} 0 ${h-14}M${x+40} ${yy+12}q6 ${h/3} 0 ${Math.max(0,h-24)}" stroke="#e4bd84" opacity=".14" fill="none"/>`}}
let debris=state.waste?'':wasteSpots.map((p,i)=>{let q=projectWaste(p);return i%3?`<path d="m${q.x-12} ${q.y-8} 19-5 10 17-20 5Z" fill="#d4c5a6" stroke="#7c6346" stroke-width="1.5"/>`:`<g transform="translate(${q.x} ${q.y})"><rect x="-15" y="-14" width="33" height="30" fill="#50361e" opacity=".25"/><rect x="-17" y="-17" width="31" height="29" fill="#b28c5a" stroke="#6f502f" stroke-width="2"/><path d="M-15-15 12 10m-27 0 27-25" stroke="#debd86" stroke-width="3"/></g>`}).join('');
return `<defs><linearGradient id="floorTone" x2=".3" y2="1"><stop stop-color="${state.floor?'#d6ac70':'#aa8960'}"/><stop offset="1" stop-color="${floor}"/></linearGradient><linearGradient id="counterWood" x2="1" y2="0"><stop stop-color="#bc8a50"/><stop offset=".5" stop-color="#d0a366"/><stop offset="1" stop-color="#966538"/></linearGradient><linearGradient id="steel" x2="1" y2="1"><stop stop-color="#d9d2b8"/><stop offset=".45" stop-color="#969c89"/><stop offset=".6" stop-color="#cec9b4"/><stop offset="1" stop-color="#7f826f"/></linearGradient><clipPath id="floorPlanClip"><rect x="202" y="125" width="1153" height="785"/></clipPath></defs><rect x="174" y="109" width="1222" height="847" rx="12" fill="#26190f" opacity=".32"/><rect x="180" y="100" width="1200" height="840" rx="3" fill="${wall}" stroke="#66482e" stroke-width="5"/><rect x="202" y="125" width="1153" height="785" fill="url(#floorTone)"/><g clip-path="url(#floorPlanClip)">${boards}<rect x="202" y="125" width="1153" height="785" fill="none" stroke="#3f2917" stroke-width="19" opacity=".12"/>${!state.clean?'<path d="M220 150H1330V890H220Z" fill="none" stroke="#d5c4a2" opacity=".14" stroke-width="38"/>':''}</g><rect x="202" y="125" width="1153" height="785" fill="none" stroke="#68492e" stroke-width="4"/><path d="M348 132H1260V158H348Z" fill="${state.clean?'#b7d5cf':'#8d9d8d'}" stroke="#614329" stroke-width="4"/>${[360,490,620,750,880,1010,1140,1250].map(x=>`<path d="M${x} 129v32" stroke="#6e4b2c" stroke-width="7"/><path d="M${x+3} 130v28" stroke="#c89c61" stroke-width="2"/>`).join('')}<path d="M350 165 460 560H1290L1250 165Z" fill="#ffe5a3" opacity="${state.clean?.19:.045}"/><rect x="213" y="205" width="131" height="614" rx="7" fill="#32230f" opacity=".3"/><rect x="213" y="200" width="118" height="610" rx="6" fill="#5f6650" stroke="#49331f" stroke-width="4"/><rect x="219" y="206" width="105" height="598" rx="4" fill="url(#counterWood)" stroke="#e4bd7e" stroke-width="2"/><path d="M230 219q-5 280 0 570M311 219q-4 280 0 570" stroke="#765029" opacity=".3" fill="none"/><rect x="238" y="276" width="70" height="111" rx="7" fill="#3a3020" opacity=".3"/><rect x="233" y="268" width="72" height="108" rx="7" fill="url(#steel)" stroke="#534833" stroke-width="3"/><path d="M244 275v85m8-85v85m40-85v85" stroke="#ece5cc" opacity=".5"/><circle cx="271" cy="292" r="14" fill="#514831" stroke="#d0cab0" stroke-width="3"/><circle cx="271" cy="341" r="14" fill="#514831" stroke="#d0cab0" stroke-width="3"/><rect x="284" y="288" width="28" height="8" rx="3" fill="#423b29"/><rect x="284" y="337" width="28" height="8" rx="3" fill="#423b29"/><circle cx="267" cy="424" r="24" fill="#514635"/><circle cx="267" cy="424" r="19" fill="#756246" stroke="#b7b395" stroke-width="4"/><circle cx="267" cy="424" r="12" fill="#342719"/><rect x="231" y="541" width="78" height="151" rx="6" fill="url(#steel)" stroke="#6d5334" stroke-width="4"/><path d="M242 550v130m52-130v130" stroke="#f7ecd3" stroke-width="4" opacity=".5"/>${[735,768].map(y=>`<circle cx="250" cy="${y}" r="11" fill="#e8dbc0" stroke="#836947" stroke-width="2"/><circle cx="250" cy="${y}" r="6" fill="#b8a485"/>`).join('')}<rect x="1287" y="232" width="63" height="584" fill="#3a2919" opacity=".22"/><rect x="1290" y="230" width="56" height="580" fill="#835b36" stroke="#60432c" stroke-width="3"/>${[290,410,530,650,770].map((y,i)=>`<path d="M1294 ${y}h48" stroke="#cfa477" stroke-width="7"/><circle cx="1308" cy="${y-19}" r="8" fill="${i%2?'#a28c63':'#d6cab0'}" stroke="#654b32" stroke-width="2"/><circle cx="1330" cy="${y-19}" r="8" fill="#b6a582" stroke="#654b32" stroke-width="2"/>`).join('')}${!state.paint?'<path d="m185 210 10 14-6 25 8 13m1165 258 12 22-10 28 8 24" stroke="#807055" stroke-width="5" fill="none"/>':''}<path d="M1356 803v89" stroke="#c49a62" stroke-width="21"/><path d="M1356 804h-79v79" fill="none" stroke="#6d5133" stroke-width="3"/><path d="M1277 883a79 79 0 0 0 79-79" fill="none" stroke="#6d5133" stroke-dasharray="5 5" opacity=".45"/>${debris}`}
